        switch ($action) {
            case 'pickDeckCard':
                self::pickDeckCard($game);
                break;
            case 'putCard':
                self::putCard($game, $args[0], $args[1], $args[2], $args[3]);
                break;
            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
